const raw = $input.first().json || {};
const body = raw.body || raw;
const message = body.message || body.edited_message || body.channel_post || {};

// Extract telegram chat ID and username
const rawChatId = message.chat?.id || message.from?.id || body.sessionId || "";
const firstName = message.from?.first_name || message.chat?.first_name || "";
const lastName = message.from?.last_name || message.chat?.last_name || "";
const username = message.from?.username || message.chat?.username || "";

const customerName = (firstName + " " + lastName).trim() || username || "Telegram User";

// Extract Message Text & ID 
const text = message.text || message.caption || body.messageText || ""; 
const messageId = message.message_id ? String(message.message_id) : 'MSG\_' + Date.now();

// Determine Message Type (assigns 'text' if text is present to pass Node 3 filter)
const messageType = (typeof text === 'string' && text.trim().length > 0) ? 'text' : 'non-text';

// Return clean normalized output for n8n pipeline
return [{
  json: {
    sessionId: String(rawChatId),
    chatId: String(rawChatId),
    customerPhone: String(rawChatId),
    customerName: customerName,
    username: username,
    messageText: text,
    messageId: messageId,
    messageType: messageType,
    platform: 'telegram',
    receivedAt: new Date().toISOString(),
    subtask: 'SUBTASK_1_INGESTION_AND_INTENT'
  }
}]
